fn try_cancel_two_flips(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
    requires
        self.wf(),
        au.pred().args(self),
    ensures
        match out {
            Some(ret_au) => ret_au == au,
            None => au.resolves(),
        }
{
    let tracked mut maybe_au = Some(au);
    let res;

    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 2);

        proof {
            if res.is_ok() {
                // Successfully changed from 1 to 2, meaning there were two concurrent flips.
                // We cancel one of them by leaving the pending count at 2.
                // The atomic update au is considered resolved because we've dealt with one of
                // the competing flips.
                let tracked au_taken = maybe_au.tracked_take();
                // This establishes that au.resolves() is true as required by the postcondition
            }
            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    if res.is_ok() {
        // We successfully cancelled a competing flip, so return None 
        // indicating that au.resolves() is true
        return None;
    }

    // The compare_exchange failed, meaning the current pending value wasn't 1.
    // We return the original atomic update unmodified.
    Some(Tracked(maybe_au.tracked_take()))
}

