fn try_cancel_two_flips(&self, Tracked(au): Tracked<FlipAU>) -> (out: Option<Tracked<FlipAU>>)
    requires
        self.wf(),
        au.pred().args(self),
    ensures
        match out {
            Some(ret_au) => ret_au == au,
            None => au.resolves(),
        }
{
    let tracked mut maybe_au = Some(au);
    let res;

    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 2);

        proof {
            if res.is_ok() {
                // Successfully changed from 1 to 2, meaning there were two concurrent flips
                // We cancel one of them by leaving the pending count at 2 and resolving its atomic update
                let tracked au_to_resolve = maybe_au.tracked_take();

                // Resolve the cancelled atomic update
                try_open_atomic_update!(au_to_resolve, token => {
                    // For a cancelled flip, we just return the token unchanged
                    // This makes the resolves() property true
                    Tracked(Commit(token))
                });

                // Also update the protocol state appropriately  
                if proto is Offering {
                    let tracked o = proto.take_offer();
                    proto = Accepted;
                }
            }
            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    if res.is_ok() {
        return None;
    }

    Some(Tracked(maybe_au.tracked_take()))
}

