    requires
        self.wf(),
        au.pred().args(self),
    ensures
        match out {
            Some(ret_au) => ret_au == au,
            None => au.resolves(),
        }
{
    let tracked mut maybe_au = Some(au);
    let res: Result<u32, u32>;

    open_atomic_invariant!(self.inv.borrow() => v => {
        let tracked (mut value_perm, mut pend_perm, mut auth, mut gv, mut proto) = v;
        res = self.pending.compare_exchange(Tracked(&mut pend_perm), 1, 2);

        proof {
            if res.is_ok() {
                // Successfully changed from 1 to 2 (there were two concurrent flips)
                let tracked au_to_resolve = maybe_au.tracked_take();

                // Verify we're in Offering state (consistent with pend_perm.value() == 1)
                assert(proto is Offering);

                // Get the atomic update that was stored in the protocol  
                let tracked stored_au = proto.take_offer();

                // Perform cancellation by resolving our atomic update with flipped semantics
                try_open_atomic_update!(au_to_resolve, mut token => {
                    // For flip semantics we must satisfy new_token@.value@ == !old_token.value@
                    // This means we must logically "flip" the token during cancellation

                    // Read the current authorized value
                    let ghost old_auth_value = auth@;

                    // Update authorization to reflect conceptual flip
                    // (Even though we don't actually flip physically)
                    auth.update(!old_auth_value);

                    // Update the token to match the new authorization
                    // This makes token.value@ equal to the new auth value (!old_auth_value)
                    auth.update(&mut token.value, !old_auth_value);

                    // Return the logically flipped token wrapped in Commit
                    Tracked(Commit(token))
                });

                // Set to Accepted to match the pending.count = 2 invariant requirement
                proto = Accepted;
            }
            v = (value_perm, pend_perm, auth, gv, proto);
        }
    });

    if res.is_ok() {
        return None;
    }

    Some(Tracked(maybe_au.tracked_take()))
}

